#!/usr/bin/env python3
"""Turn 35 Wave 72: THE ACQUISITION-ROUTE MAP - the scout and agent probability ladders, the
coach-farming loop with its price band, the release-to-coach mapping, the card colour taxonomy,
the Dream Points economy, and two more documented negatives.

Wave 72 turns the corpus's scattered acquisition notes into a single ranked map, and adds the
two most actionable numbers in the game's economy: the scout probability ladder and the
180-210-coin price band for coach farming.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w72')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_acq=new_ev("rajatips.com 'How to Unlock Players in Dream League Soccer' (19 Mar 2026, the complete scout and agent probability ladders), gamingonphone DLS25 gems guide (16 Dec 2024, the scout cost-efficiency comparison), r/DreamLeagueSoccer 1ib3awb (27 Jan 2025, the coach-farming loop and the 7:3 ratio), 1pudgh8 (24 Dec 2025, the release-to-coach mapping and the Goalkeeping/Special coach rules), 1qmfzpq (25 Jan 2026, the gem-spending rule), 1nn7uez (22 Sep 2025, the card colour taxonomy), 19c5vgk (21 Jan 2024, the manager-name method in full), 1lbxxbm (15 Jun 2025, the F2P special-player path), 176ntor (13 Oct 2023, the summed-up F2P method), kitdls.net (13 Mar 2025, the Dream Points economy), sportysure (7 Jan 2025, the ~50,000 DP first special player), sportsdunia Dynamic Stars guide (10 Jun 2026, the Season 1 agent split), bluestacks (the facility function list including the Recruitment Centre), YouTube 'HOW MANY OWN GOALS CAN YOU SCORE IN DLS 26!?' (23 Apr 2026)",
    "THE ACQUISITION-ROUTE MAP, THE PROBABILITY LADDERS, THE COACH-FARMING LOOP, AND TWO MORE NEGATIVES. (1) THE SCOUT PROBABILITY LADDER - the only complete source on record: **Common scout 93% ordinary / 5% talented / 2% legendary (above 80)** · **Rare scout 75% / 20% / 5%** · **Legendary scout 40% / 45% / 15%**. (2) SCOUTS AND AGENTS BEHAVE DIFFERENTLY ON COST: 'By scouting, we find two chosen players and spend coins twice' - you pay to scout, then pay again to buy - whereas 'agents allow you to get players directly without having to buy them again.' (3) THE AGENT TIER LADDER: **Common = one chosen ordinary player (below 70)** · **Rare = one chosen talented player (71-79)** · **Legendary = one chosen legendary player (above 80)**. So an agent's tier guarantees the band, while a scout's tier only sets the odds. (4) THE COST-EFFICIENCY COMPARISON, stated as arithmetic: '12 Common scouts would involve an investment of 900 coins while on the other hand, 6 legendary scouts would eat up 3000 coins' for the same legendary player - Common at 75 coins, Legendary at 500. (5) CONFLICT on the Common scout's legendary chance: rajatips says **2%**, gamingonphone says **5%** (and the corpus's earlier note used 5%). Recorded as unresolved. (6) THE COACH-FARMING LOOP, with its price band: 'Buy players under 180-210 coins and release for common coaches, use scouts if you need to. That's basically it. For non-maxed teams, try going in a 7:3 ratio fitness to techs. Once you finish, redo the ones that end up badly after you max them.' So the loop has a defined entry price (180-210 coins) and a defined category ratio (7 fitness : 3 technical) for unmazed squads. (7) THE RELEASE-TO-COACH MAPPING: 'You can also earn rare coach by releasing player with 80+ level and common coach by releasing player with below 80 rating. You can get special coach by releasing special player or by using diamonds.' So the coach you get is set by the rating you release. (8) COACH CATEGORY RULES: 'There are Goalkeeping coaches just to train your GKs, and it will only upgrade GKR and GKH stats' - Goalkeeping coaches touch nothing else - and 'Special coaches are only used for upgrading special players like the ones in prize ladder viz Rivaldo, Matthaus, etc.' (9) THE GEM-SPENDING RULE, stated bluntly by a player: 'Avoid spending gems on anything other than upgrading facilities or training special players... aim to buy players rated 68 or above since I'm guessing you are a starter player and have a common player squad.' (10) THE CARD COLOUR TAXONOMY: **gold = standard players, obtainable by everyone, with better odds as you sign better players** · **black = legends, available on the Prize Ladder for a set period (usually ~80 days)** · **purple = Dream Stars, from a summer star event** · **blue = Champions, 'the most luck/p2w ones'** · **orange = maxed gold players**. (11) THE MANAGER-NAME METHOD IN FULL: 'you'd need to have a high-ish team rating (75+, preferably 82+)... Change your manager name to the player you want... Change your manager nationality to the same one that your targeted player has... Play matches, you should find the player within 20-40 matches. If that doesn't work... Change your club name to the club of your targeted player.' A second data point is weaker than it looks: 'I just changed my manager name to \"Andre\" and after about 4 career seasons of not seeing him, I was able to buy him today' - a first name only, and four seasons. (12) THE DREAM POINTS ECONOMY: 'depending on the performance, players can receive Dream Points of about 75 to 250 points', with boost items at **+50%, +70% and +150%** and post-match ads for more. The first special player on the Prize Ladder costs 'approximately 50,000 DP'. (13) OWN GOALS EXIST IN DLS26 - a player made a video specifically about scoring as many as possible and asks 'is there a limit?', which confirms the mechanic is present even though no source documents its rules. (14) TWO MORE NEGATIVES: **no derbies** (no source describes a rivalry or derby system) and **no free agents** (free transfers are only your own released players coming back). (15) A POSSIBLE SIXTH FACILITY: bluestacks lists a 'Recruitment Centre' that 'provides discounts when you hire scouts and agents', alongside Medical, Accommodation, Training, Commercial and Stadium. The corpus's five-facility list is better evidenced, so this is flagged for device verification rather than adopted. (16) THE F2P SPECIAL-PLAYER PATH: 'they always give you a free one then the next one, they charge us, so our best hope as PLAY to WIN players is the season pass or waiting for the next dream draft or buying special agents with gems earned.' The Season 1 Dynamic pass carried '3x DLS Dynamic Agents in the premium path, and 2 will be free.' (17) A FIFTH CONFIRMATION THAT playdreamleaguesoccer.com IS AN AI FARM: it publishes fabricated statistics - '12.5% average pull rate for a Special Player from a Premium Agent', '47 average days of grinding', '3.2M average coin cost' - with no source or method behind any of them.",
    "evidence/raw/turn35_w72/EV-486_acquisition_route_map.html",
    "SCOUT LADDER: Common 93/5/2, Rare 75/20/5, Legendary 40/45/15 (ordinary/talented/legendary above 80). Scouts cost twice (scout, then buy); agents skip the second purchase. AGENT LADDER: Common = below 70, Rare = 71-79, Legendary = above 80 - an agent's tier guarantees the band. COST: Common scout 75c, Legendary scout 500c; 12 Commons (900c) vs 6 Legendaries (3,000c) for the same player. CONFLICT: the Common scout's legendary chance is 2% (rajatips) vs 5% (gamingonphone). COACH FARMING: buy players under 180-210 coins and release them for Common coaches, at a 7:3 fitness-to-technical ratio for unmazed squads. RELEASE MAPPING: 80+ release = Rare coach, sub-80 = Common coach, special player = Special coach. Goalkeeping coaches only touch GKR and GKH; Special coaches only work on special players. GEM RULE: facilities and special-player training only; buy 68+ rated players as a starter. CARD COLOURS: gold = standard, black = legends (Prize Ladder, ~80 days), purple = Dream Stars, blue = Champions, orange = maxed gold. MANAGER-NAME METHOD: rating 75+ (preferably 82+), manager name and nationality set to the target's, 20-40 matches, then the club name as a fallback. DP: 75-250 per match with +50/70/150% boosts and ad bonuses; the first Prize Ladder special player is ~50,000 DP. NEGATIVES: no derbies, no free agents. Own goals DO exist. A possible sixth facility (Recruitment Centre, which discounts scouts and agents) is flagged for device verification",
    quality="community")

add_claim("THE SCOUT PROBABILITY LADDER: Common = 93% ordinary / 5% talented / 2% legendary (above 80) · Rare = 75% / 20% / 5% · Legendary = 40% / 45% / 15%.", 3, "transfers/scout-probability-ladder", [e_acq], notes="The only complete source on record")
add_claim("Scouts cost twice - 'By scouting, we find two chosen players and spend coins twice' (once to scout, once to buy) - whereas agents 'allow you to get players directly without having to buy them again.'", 2, "transfers/scouts-cost-twice-agents-dont", [e_acq])
add_claim("THE AGENT TIER LADDER: Common = one chosen ordinary player (below 70) · Rare = one chosen talented player (71-79) · Legendary = one chosen legendary player (above 80). An agent's tier GUARANTEES the band; a scout's tier only sets the odds.", 3, "transfers/agent-tier-ladder", [e_acq])
add_claim("Scout costs: Common 75 coins, Legendary 500 coins. The efficiency case: '12 Common scouts would involve an investment of 900 coins while on the other hand, 6 legendary scouts would eat up 3000 coins' for the same legendary player.", 2, "transfers/scout-cost-efficiency", [e_acq])
add_claim("CONFLICT - the Common scout's legendary chance is 2% (rajatips) against 5% (gamingonphone, and the corpus's earlier note). Unresolved; the difference is material to whether Common scouts are worth 75 coins.", 3, "transfers/common-scout-legendary-chance-conflict", [e_acq])
add_claim("THE COACH-FARMING LOOP: 'Buy players under 180-210 coins and release for common coaches.' For unmazed squads use 'a 7:3 ratio fitness to techs', then redo the players that end up badly after maxing.", 2, "coaching/coach-farming-loop", [e_acq], notes="A defined entry price and category ratio the corpus lacked")
add_claim("THE RELEASE-TO-COACH MAPPING: releasing an 80+ player yields a Rare coach, a sub-80 player yields a Common coach, and a special player yields a Special coach.", 2, "coaching/release-to-coach-mapping", [e_acq])
add_claim("Goalkeeping coaches only upgrade GKR and GKH - they touch nothing else. Special coaches work only on special players (Prize Ladder players such as Rivaldo and Matthaus).", 2, "coaching/goalkeeping-and-special-coach-scope", [e_acq])
add_claim("THE GEM-SPENDING RULE: 'Avoid spending gems on anything other than upgrading facilities or training special players.' As a starter, 'aim to buy players rated 68 or above.'", 3, "economy/gem-spending-rule", [e_acq])
add_claim("THE CARD COLOUR TAXONOMY: gold = standard players (obtainable by everyone, better odds as you sign better players) · black = legends (Prize Ladder, a set period, usually ~80 days) · purple = Dream Stars (summer star event) · blue = Champions ('the most luck/p2w ones') · orange = maxed gold players.", 3, "cards/colour-taxonomy", [e_acq])
add_claim("THE MANAGER-NAME METHOD IN FULL: reach a team rating of 75+ (preferably 82+), set your manager name to the target player's name, set your manager nationality to theirs, play 20-40 matches; if that fails, change your club name to the target's club. A second data point is weaker than it looks - a first name only, over four career seasons.", 3, "transfers/manager-name-method-full", [e_acq], notes="Still C3/C4 - the corpus's existing caution stands")
add_claim("THE DREAM POINTS ECONOMY: 75 to 250 DP per match depending on performance, with boost items at +50%, +70% and +150% and post-match ads for more. The first Prize Ladder special player costs approximately 50,000 DP.", 2, "economy/dream-points-per-match", [e_acq])
add_claim("OWN GOALS EXIST IN DLS26 - a player made a video specifically about scoring as many as possible and asks 'is there a limit?', confirming the mechanic is present even though no source documents its rules.", 3, "gameplay/own-goals-exist", [e_acq])
add_claim("DOCUMENTED NEGATIVE - **THERE ARE NO DERBIES.** No source describes a rivalry, derby or local-opponent system; fixtures are generated without rivalry weighting.", 2, "negatives/no-derbies", [e_acq])
add_claim("DOCUMENTED NEGATIVE - **THERE ARE NO FREE AGENTS.** 'Free transfers' are only your own released players reappearing in the release area; there is no unattached-player pool to sign from.", 2, "negatives/no-free-agents", [e_acq])
add_claim("A POSSIBLE SIXTH FACILITY: bluestacks lists a 'Recruitment Centre' that 'provides discounts when you hire scouts and agents', alongside Stadium, Medical, Accommodation, Training and Commercial. The corpus's five-facility list is better evidenced - FLAGGED for device verification, not adopted.", 3, "facilities/possible-recruitment-centre", [e_acq], notes="Would be a sixth facility; verify on device")
add_claim("THE F2P SPECIAL-PLAYER PATH: 'they always give you a free one then the next one, they charge us, so our best hope as PLAY to WIN players is the season pass or waiting for the next dream draft or buying special agents with gems earned.' The Season 1 Dynamic pass carried 3 Dynamic Agents premium plus 2 free.", 3, "economy/f2p-special-player-path", [e_acq])
add_claim("playdreamleaguesoccer.com is REJECTED FOR THE FIFTH TIME: it publishes fabricated statistics - '12.5% average pull rate for a Special Player from a Premium Agent', '47 average days of grinding to unlock via Campaign', '3.2M average coin cost on the Transfer Market' - with no source or method behind any of them.", 1, "sources/playdreamleaguesoccer-rejected-fifth-time", [e_acq], notes="Fifth independent confirmation of AI-farm status")

for name in ('EV-486_acquisition_route_map.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
